public function buildExcelFunctionCatalog(): array
{
    $catalog = [];
    foreach ($this->allFunctionNames() as $functionName) {
        $meta = $this->describeExcelFunction($functionName);
        if ($meta !== null) {
            $catalog[$functionName] = $meta;
        }
    }

    return $catalog;
}

